  const ExItem(no: 'G06', title: '중복 제거하기', category: 'G', categoryName: '리스트', difficulty: '기초', hardware: '화면', type: 'text', description: 'set()으로 리스트의 중복을 제거합니다.', pythonCode: "nums = [3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5]\n\nprint(f'원본 ({len(nums)}개): {nums}')\n\nunique = list(set(nums))\nunique.sort()\nprint(f'중복제거 ({len(unique)}개): {unique}')\n\n# 순서 유지 중복 제거\nseen = []\nfor n in nums:\n    if n not in seen:\n        seen.append(n)\nprint(f'순서유지 ({len(seen)}개): {seen}')", expectedOutput: "원본 (11개): [3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5]\n중복제거 (7개): [1, 2, 3, 4, 5, 6, 9]\n순서유지 (7개): [3, 1, 4, 5, 9, 2, 6]", steps: ['set()으로 중복을 자동 제거합니다', '리스트로 다시 변환합니다', '순서를 유지하려면 직접 검사합니다'], concepts: [{'term': 'set()', 'desc': '중복을 허용하지 않는 집합 자료구조예요.'}, {'term': 'list(set(...))', 'desc': 'set으로 중복 제거 후 다시 리스트로 변환해요.'}, {'term': 'not in', 'desc': '리스트에 이미 있는지 확인하여 중복 방지해요.'}], quizQ: 'set([1,1,2,2,3])의 결과는?', quizOpts: ['[1,2,3]', '{1,2,3}', '[1,1,2,2,3]', '5'], quizAns: 1, quizExplain: 'set은 중복을 제거! {1,2,3}이 돼요.'),
  const ExItem(no: 'G07', title: '버블 정렬', category: 'G', categoryName: '리스트', difficulty: '고급', hardware: '화면', type: 'text', description: '가장 기본적인 정렬 알고리즘인 버블 정렬을 직접 구현합니다.', pythonCode: "nums = [64, 34, 25, 12, 22, 11, 90]\nprint(f'정렬 전: {nums}')\n\nn = len(nums)\nfor i in range(n - 1):\n    for j in range(n - 1 - i):\n        if nums[j] > nums[j + 1]:\n            nums[j], nums[j+1] = nums[j+1], nums[j]\n    print(f'{i+1}회차: {nums}')\n\nprint(f'정렬 후: {nums}')", expectedOutput: "정렬 전: [64, 34, 25, 12, 22, 11, 90]\n1회차: [34, 25, 12, 22, 11, 64, 90]\n2회차: [25, 12, 22, 11, 34, 64, 90]\n...\n정렬 후: [11, 12, 22, 25, 34, 64, 90]", steps: ['인접한 두 수를 비교합니다', '왼쪽이 크면 위치를 교환합니다', '한 바퀴 돌 때마다 가장 큰 수가 끝으로 이동합니다'], concepts: [{'term': '버블 정렬', 'desc': '인접한 두 요소를 비교-교환하며 큰 값을 뒤로 보내는 정렬이에요.'}, {'term': 'swap', 'desc': 'a, b = b, a로 두 변수의 값을 교환해요.'}, {'term': 'O(n²)', 'desc': '이중 반복이므로 데이터가 많으면 느려요.'}], quizQ: '버블 정렬에서 한 바퀴 후 확실한 것은?', quizOpts: ['전부 정렬됨', '가장 큰 수가 맨 뒤', '가장 작은 수가 맨 앞', '절반 정렬됨'], quizAns: 1, quizExplain: '한 바퀴 돌면 가장 큰 수가 끝으로 "떠올라" 가요!'),
  const ExItem(no: 'G08', title: '스택과 큐', category: 'G', categoryName: '리스트', difficulty: '중급', hardware: '화면', type: 'text', description: '리스트로 스택(LIFO)과 큐(FIFO)를 구현합니다.', pythonCode: "# 스택 (LIFO: 후입선출)\nstack = []\nstack.append('A')\nstack.append('B')\nstack.append('C')\nprint(f'스택: {stack}')\nprint(f'pop: {stack.pop()}')\nprint(f'pop: {stack.pop()}')\nprint(f'남은: {stack}')\n\nprint()\n\n# 큐 (FIFO: 선입선출)\nfrom collections import deque\nqueue = deque()\nqueue.append('1번')\nqueue.append('2번')\nqueue.append('3번')\nprint(f'큐: {list(queue)}')\nprint(f'처리: {queue.popleft()}')\nprint(f'처리: {queue.popleft()}')\nprint(f'남은: {list(queue)}')", expectedOutput: "스택: ['A', 'B', 'C']\npop: C\npop: B\n남은: ['A']\n\n큐: ['1번', '2번', '3번']\n처리: 1번\n처리: 2번\n남은: ['3번']", steps: ['스택: append로 넣고 pop으로 꺼냅니다', '큐: append로 넣고 popleft로 꺼냅니다', '스택은 마지막 것, 큐는 처음 것이 먼저 나옵니다'], concepts: [{'term': '스택 (LIFO)', 'desc': '마지막에 넣은 것이 먼저 나와요. 접시 쌓기처럼!'}, {'term': '큐 (FIFO)', 'desc': '먼저 넣은 것이 먼저 나와요. 줄 서기처럼!'}, {'term': 'deque', 'desc': '양쪽에서 넣고 뺄 수 있는 효율적인 자료구조예요.'}], quizQ: '스택에 1,2,3 넣고 pop하면?', quizOpts: ['1', '2', '3', '1,2,3'], quizAns: 2, quizExplain: '스택은 LIFO! 마지막에 넣은 3이 먼저 나와요.'),
  const ExItem(no: 'G09', title: '투표 집계 (빈도수)', category: 'G', categoryName: '리스트', difficulty: '중급', hardware: '화면', type: 'text', description: '딕셔너리로 투표 결과를 집계합니다.', pythonCode: "votes = ['민수','영희','민수','철수','영희','민수','영희','철수','민수']\n\ncount = {}\nfor v in votes:\n    count[v] = count.get(v, 0) + 1\n\nprint('=== 투표 결과 ===')\nfor name, cnt in sorted(count.items(), key=lambda x: -x[1]):\n    bar = '█' * cnt\n    print(f'{name}: {cnt}표 {bar}')\n\nwinner = max(count, key=count.get)\nprint(f'\\n당선: {winner} ({count[winner]}표)')", expectedOutput: "=== 투표 결과 ===\n민수: 4표 ████\n영희: 3표 ███\n철수: 2표 ██\n\n당선: 민수 (4표)", steps: ['각 이름의 등장 횟수를 셉니다', '득표순으로 정렬합니다', '가장 많은 표를 받은 사람이 당선'], concepts: [{'term': 'dict.get(key, 0)', 'desc': '키가 없으면 0을 반환하는 안전한 방법이에요.'}, {'term': 'max(dict, key=)', 'desc': '값 기준으로 가장 큰 키를 찾아요.'}, {'term': '빈도수 카운팅', 'desc': '각 항목이 몇 번 나오는지 세는 패턴이에요.'}], quizQ: "count.get('없는키', 0)의 결과는?", quizOpts: ['에러', 'None', '0', "'없는키'"], quizAns: 2, quizExplain: "키가 없으면 기본값 0을 반환해요!"),
  const ExItem(no: 'G10', title: '튜플과 언패킹', category: 'G', categoryName: '리스트', difficulty: '중급', hardware: '화면', type: 'text', description: '튜플의 특성과 언패킹 활용법을 배웁니다.', pythonCode: "# 튜플 기본\npoint = (3, 4)\nx, y = point  # 언패킹\nprint(f'좌표: ({x}, {y})')\n\n# 함수에서 여러 값 반환\ndef min_max(nums):\n    return min(nums), max(nums)\n\ndata = [5, 3, 8, 1, 9, 2]\nlo, hi = min_max(data)\nprint(f'최소: {lo}, 최대: {hi}')\n\n# swap\na, b = 10, 20\na, b = b, a\nprint(f'교환: a={a}, b={b}')", expectedOutput: "좌표: (3, 4)\n최소: 1, 최대: 9\n교환: a=20, b=10", steps: ['튜플로 여러 값을 묶습니다', '언패킹으로 각 변수에 분리합니다', '함수에서 여러 값을 반환할 때 유용합니다'], concepts: [{'term': '튜플', 'desc': '(1, 2, 3)처럼 수정 불가능한 리스트예요.'}, {'term': '언패킹', 'desc': 'x, y = (3, 4)처럼 튜플의 값을 변수에 풀어내요.'}, {'term': '다중 반환', 'desc': 'return a, b로 함수에서 여러 값을 반환해요.'}], quizQ: 'a, b = 1, 2 후 a와 b는?', quizOpts: ['a=1 b=2', 'a=2 b=1', 'a=(1,2)', '에러'], quizAns: 0, quizExplain: 'a에 1, b에 2가 각각 들어가요!'),

